package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.*;import android.graphics.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
/** Explicitly entered commands only. History stays in memory; root is opt-in. */
public final class TerminalActivity extends LeoActivity {
    private final Handler updates=new Handler();private final StringBuilder buffer=new StringBuilder();private final ArrayList<String> history=new ArrayList<String>();private TextView output,sessionLabel;private EditText command;private ScrollView scroll;private TerminalSession session;private int at;private volatile boolean destroyed;private boolean scrollMode;private final java.util.concurrent.atomic.AtomicBoolean queued=new java.util.concurrent.atomic.AtomicBoolean();
    private final Runnable display=new Runnable(){public void run(){queued.set(false);if(destroyed)return;String text; synchronized(buffer){text=buffer.toString();}output.setText(text);scroll.post(new Runnable(){public void run(){if(!scrollMode&&!destroyed)scroll.fullScroll(View.FOCUS_DOWN);}});}};
    protected void onCreate(Bundle state){super.onCreate(state);begin(L.t("Terminal Leo"));sessionLabel=text(L.t("Shell local · su disponibil"),12);root.addView(sessionLabel);scroll=new ScrollView(this);output=text("",13);output.setTypeface(Typeface.MONOSPACE);output.setTextColor(0xff9df5c1);scroll.addView(output);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));command=new EditText(this);command.setSingleLine(true);command.setTextColor(Color.WHITE);command.setTextSize(16);command.setTypeface(Typeface.MONOSPACE);command.setHint(L.t("Comandă…"));command.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);command.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_GO);command.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(4096)});root.addView(command);command.setOnEditorActionListener(new TextView.OnEditorActionListener(){public boolean onEditorAction(TextView v,int action,KeyEvent event){execute();return true;}});command.setOnKeyListener(new View.OnKeyListener(){public boolean onKey(View v,int key,KeyEvent e){if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(e.getAction()==0&&e.getRepeatCount()==0)execute();return true;}if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){if(e.getAction()==0&&!history.isEmpty()){at=Math.max(0,Math.min(history.size(),at+(key==KeyEvent.KEYCODE_DPAD_UP?-1:1)));command.setText(at==history.size()?"":history.get(at));command.setSelection(command.length());}return true;}return false;}});form=true;left=new Runnable(){public void run(){menu();}};footer(L.t("Opțiuni"),L.t("Execută"),L.t("Șterge"));command.requestFocus();start();}
    private void append(String value){if(destroyed)return;synchronized(buffer){buffer.append(value.replaceAll("\\x1B\\[[0-9;?]*[ -/]*[@-~]",""));if(buffer.length()>32768)buffer.delete(0,buffer.length()-32768);}if(queued.compareAndSet(false,true))updates.postDelayed(display,60);}
    private void start(){start(false);}
    private void start(boolean rootMode){sessionLabel.setText(rootMode?L.t("Sesiune root · verifică prin id"):L.t("Shell local · su disponibil"));session=new TerminalSession(rootMode?"/system/bin/leo-su":"/system/bin/sh");try{session.start(getFilesDir(),new TerminalSession.Output(){public void text(String value){append(value);}});append(rootMode?L.t("Leo root · sesiune nouă\n"):L.t("Leo shell · sesiune nouă\n"));if(rootMode)session.send("id");}catch(IOException e){append(L.t("Shell indisponibil\n"));}}
    private void execute(){String value=command.getText().toString();if(value.isEmpty())return;append("\n$ "+value+"\n");history.add(value);if(history.size()>30)history.remove(0);at=history.size();command.setText("");final String line=value;final TerminalSession current=session;worker.execute(new Runnable(){public void run(){try{current.send(line);}catch(IOException e){append(L.t("Sesiune închisă · Opțiuni → Sesiune nouă\n"));}}});}
    private void symbols(){final String[] chars={"|",">","<","&","$","'","\"","\\","`","[","]","{","}","~",";","*"};options(L.t("Simboluri shell"),chars,new Choice(){public void pick(int i){int start=Math.max(0,command.getSelectionStart()),end=Math.max(start,command.getSelectionEnd());command.getText().replace(start,end,chars[i]);command.setSelection(start+chars[i].length());command.requestFocus();}});}
    private void menu(){options("Terminal",new String[]{L.t("Execută"),L.t("Comenzi rapide"),L.t("Simboluri shell"),L.t("Derulează rezultatul"),L.t("Curăță ecranul"),L.t("Sesiune nouă"),L.t("Sesiune root"),L.t("Despre")},new Choice(){public void pick(int i){if(i==0)execute();else if(i==1)options(L.t("Comenzi rapide"),new String[]{"pwd","id","uname -a","ls -la","df -h"},new Choice(){public void pick(int n){command.setText(new String[]{"pwd","id","uname -a","ls -la","df -h"}[n]);command.setSelection(command.length());}});else if(i==2)symbols();else if(i==3){scrollMode=true;scroll.setFocusableInTouchMode(true);scroll.requestFocus();notice(L.t("Sus/jos derulează · OK revine la comandă"));}else if(i==4){synchronized(buffer){buffer.setLength(0);}updates.post(display);}else if(i==5){session.close();start();}else if(i==6){if(!new File("/system/bin/leo-su").canExecute()){notice(L.t("Helperul root nu este instalat"));return;}session.close();start(true);}else notice(L.t("OK execută · sus/jos istoric · taste Leo pentru text. Shell fără PTY; aplicațiile interactive de tip vi nu sunt suportate."));}});}
    public boolean dispatchKeyEvent(KeyEvent event){int key=event.getKeyCode();if(scrollMode){if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){if(event.getAction()==0)scroll.smoothScrollBy(0,dp(key==KeyEvent.KEYCODE_DPAD_UP?-54:54));return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_BACK){if(event.getAction()==0){scrollMode=false;command.requestFocus();}return true;}}return super.dispatchKeyEvent(event);}
    protected void onDestroy(){destroyed=true;if(session!=null)session.close();updates.removeCallbacksAndMessages(null);super.onDestroy();}
}
